+});
+
+afterEach(() => {
+    jest.useRealTimers();
+});
+
+const wrapper = hookWrapper(withEventManager());
+
+it('should return a function', () => {
+    const { result } = renderHook(() => usePollEvents(), { wrapper });
+    expect(typeof result.current).toBe('function');
+});
+
