+        eventProperty: 'PaymentMethods',
+        subscribeToProperty: 'PaymentMethods',
+        action: EVENT_ACTIONS.CREATE,
+    },
+    {
+        type: 'wrong property',
+        event: [
+            {
+                Action: EVENT_ACTIONS.CREATE,
+            },
+        ],
+        eventProperty: 'WrongProperty',
+        subscribeToProperty: 'PaymentMethods',
+        action: EVENT_ACTIONS.CREATE,
+    },
